        //String name = getFnName().toString();
        List<FType> l = null;
        try {
            l = getDomain();
        }
        catch (Throwable th) {
            ; /* do nothing */
        }
        return (s(selfType)) + (l == null ? "(DOMAIN_ERROR null)" : Useful.listInParens(l)) + cfn.at();
    }

