        if (defs.size() > 0) {
            // Minor optimization, avoid this if no defs to eval.
            EvalVarsEnvironment eve = new EvalVarsEnvironment(lex_env.extend(self_env), self_env);
            visitDefs(eve); // HACK here's where we add to self_env.
